def transform_fixed(grid):
    h, w = len(grid), len(grid[0])

    # Find background
    color_counts = {}
    for r in range(h):
        for c in range(w):
            color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1
    background = max(color_counts, key=color_counts.get)

    # Find marker column
    marker_col = None
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            marker_col = c
            break

    # Find object color
    object_color = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background and grid[r][c] != 2:
                object_color = grid[r][c]
                break
        if object_color:
            break

    # Calculate shift
    object_leftmost = None
    for c in range(w):
        if any(grid[r][c] == object_color for r in range(h)):
            object_leftmost = c
            break

    shift = object_leftmost - (marker_col + 1)

    # Find rightmost object
    object_rightmost = None
    for c in range(w-1, -1, -1):
        if any(grid[r][c] == object_color for r in range(h)):
            object_rightmost = c
            break

    # Spanner column: rightmost_output + 1 = (object_rightmost - shift) + 1
    spanner_col = (object_rightmost - shift) + 1

    # Spanner color: new color not in input
    input_colors = set(grid[r][c] for r in range(h) for c in range(w))
    spanner_color = 8 if 8 not in input_colors else 5

    # Apply transformation
    result = [[background for _ in range(w)] for _ in range(h)]

    for r in range(h):
        result[r][marker_col] = 2

    for r in range(h):
        for c in range(w):
            if grid[r][c] == object_color:
                new_c = c - shift
                if 0 <= new_c < w:
                    result[r][new_c] = object_color

    # Add spanner
    for r in range(h):
        if 0 <= spanner_col < w:
            result[r][spanner_col] = spanner_color

    return result

